package com.pousada.marealba;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.*;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.*;
import static org.hamcrest.Matchers.*;

@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class SystemIT {

    private static Process serverProcess;
    private static final String TEST_DB_URL = "jdbc:postgresql://localhost:5432/marealba_test";
    private static final String TEST_DB_USER = "postgres";
    private static final String TEST_DB_PASSWORD = "postgres";
    private static final int TEST_PORT = 7071;

    @BeforeAll
    public static void setup() throws Exception {
        cleanDatabase();

        ProcessBuilder pb = new ProcessBuilder(
            "java",
            "-jar",
            "target/mare-alta-1.0.0.jar"
        );

        Map<String, String> env = pb.environment();
        env.put("DB_URL", TEST_DB_URL);
        env.put("DB_USER", TEST_DB_USER);
        env.put("DB_PASSWORD", TEST_DB_PASSWORD);
        env.put("PORT", String.valueOf(TEST_PORT));

        pb.redirectErrorStream(true);
        serverProcess = pb.start();

        Thread.sleep(3000);

        RestAssured.baseURI = "http://localhost";
        RestAssured.port = TEST_PORT;
    }

    @AfterAll
    public static void tearDown() {
        if (serverProcess != null) {
            serverProcess.destroy();
        }
    }

    private static void cleanDatabase() throws Exception {
        try (Connection conn = DriverManager.getConnection(TEST_DB_URL, TEST_DB_USER, TEST_DB_PASSWORD);
             Statement stmt = conn.createStatement()) {
            stmt.execute("DROP TABLE IF EXISTS messages");
            stmt.execute("DROP TABLE IF EXISTS reservations");
            stmt.execute("DROP TABLE IF EXISTS rooms");
        }
    }

    @Test
    @Order(1)
    public void testGetRooms() {
        given()
            .when()
            .get("/rooms")
            .then()
            .statusCode(200)
            .body("size()", is(5))
            .body("[0].number", is(101))
            .body("[0].type", is("STANDARD"))
            .body("[0].capacity", is(2))
            .body("[0].nightlyRate", is(249.90f));
    }

    @Test
    @Order(2)
    public void testCreateReservation() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", 101);
        request.put("guestName", "João Silva");
        request.put("guestEmail", "joao@example.com");
        request.put("guestCpf", "12345678901");
        request.put("checkIn", "2027-07-10");
        request.put("checkOut", "2027-07-12");
        request.put("guests", 2);
        request.put("ratePlan", "STANDARD");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", notNullValue())
            .body("roomNumber", is(101))
            .body("status", is("PENDING"))
            .body("nights", is(2))
            .body("subtotal", is(599.76f))
            .body("discount", is(0.00f))
            .body("total", is(599.76f));
    }

    @Test
    @Order(3)
    public void testConfirmReservation() {
        given()
            .when()
            .post("/reservations/1/confirmation")
            .then()
            .statusCode(200)
            .body("status", is("CONFIRMED"))
            .body("amountPaid", is(599.76f));
    }

    @Test
    @Order(4)
    public void testGetMessages() {
        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("size()", is(1))
            .body("[0].channel", is("EMAIL"))
            .body("[0].to", is("joao@example.com"))
            .body("[0].subject", is("Reserva confirmada - Pousada Maré Alta"));
    }

    @Test
    @Order(5)
    public void testRoomUnavailable() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", 101);
        request.put("guestName", "Maria Santos");
        request.put("guestEmail", "maria@example.com");
        request.put("guestCpf", "98765432109");
        request.put("checkIn", "2027-07-11");
        request.put("checkOut", "2027-07-13");
        request.put("guests", 1);
        request.put("ratePlan", "STANDARD");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(409)
            .body("error", is("ROOM_UNAVAILABLE"));
    }

    @Test
    @Order(6)
    public void testCapacityExceeded() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", 101);
        request.put("guestName", "Pedro Costa");
        request.put("guestEmail", "pedro@example.com");
        request.put("guestCpf", "11122233344");
        request.put("checkIn", "2027-08-10");
        request.put("checkOut", "2027-08-12");
        request.put("guests", 5);
        request.put("ratePlan", "STANDARD");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(422)
            .body("error", is("CAPACITY_EXCEEDED"));
    }

    @Test
    @Order(7)
    public void testNonRefundablePlan() {
        Map<String, Object> request = new HashMap<>();
        request.put("roomNumber", 201);
        request.put("guestName", "Ana Lima");
        request.put("guestEmail", "ana@example.com");
        request.put("guestCpf", "55566677788");
        request.put("checkIn", "2027-03-10");
        request.put("checkOut", "2027-03-12");
        request.put("guests", 2);
        request.put("ratePlan", "NON_REFUNDABLE");

        given()
            .contentType(ContentType.JSON)
            .body(request)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("subtotal", is(779.80f))
            .body("discount", is(116.97f))
            .body("total", is(662.83f));
    }

    @Test
    @Order(8)
    public void testCheckInAndCheckOut() {
        given()
            .when()
            .post("/reservations/2/confirmation")
            .then()
            .statusCode(200);

        given()
            .when()
            .post("/reservations/2/check-in")
            .then()
            .statusCode(200)
            .body("status", is("CHECKED_IN"));

        given()
            .when()
            .post("/reservations/2/check-out")
